class Calculator:
    """
    A calculator class that performs arithmetic operations and records history.
    """

    def __init__(self):
        self._history: List[HistoryEntry] = []
        self._suppress_recording: bool = False
        self._memory: Optional[float] = None

    def _record(self, op: str, a: float, b: float, result: float, expression: str = "") -> None:
        """Internal helper to record operations to history unless suppressed."""
        if not self._suppress_recording:
            self._history.append(HistoryEntry(float(a), float(b), float(result), expression, op))

    def _check_zero(self, b: float) -> None:
        """Validates that a divisor is not zero using floating-point tolerance."""
        if math.isclose(b, 0, abs_tol=1e-15):
            raise ValueError("Division or modulo by zero is not allowed.")

    def add(self, a: float, b: float) -> float:
        res = float(a) + float(b)
        self._record("add", a, b, res)
        return res

    def subtract(self, a: float, b: float) -> float:
        res = float(a) - float(b)
        self._record("subtract", a, b, res)
        return res

    def multiply(self, a: float, b: float) -> float:
        res = float(a) * float(b)
        self._record("multiply", a, b, res)
        return res

    def divide(self, a: float, b: float) -> float:
        self._check_zero(b)
        res = float(a) / float(b)
        self._record("divide", a, b, res)
        return res

    def negate(self, a: float) -> float:
        res = -float(a)
        self._record("negate", a, 0.0, res)
        return res

    def power(self, base: float, exp: float) -> float:
        base, exp = float(base), float(exp)
        if base == 0 and exp < 0:
            raise ValueError("Cannot raise zero to a negative power.")
        try:
            res = pow(base, exp)
        except (ValueError, OverflowError, ZeroDivisionError) as e:
            raise ValueError(f"Math error: {e}")

        if isinstance(res, complex):
            raise TypeError("Result is a complex number.")

        val = float(res)
        self._record("power", base, exp, val)
        return val

    def modulo(self, a: float, b: float) -> float:
        self._check_zero(b)
        res = float(a) % float(b)
        self._record("modulo", a, b, res)
        return res

    def get_history(self) -> List[HistoryEntry]:
        return list(self._history)

    def clear_history(self) -> None:
        self._history.clear()

    def evaluate(self, expression: str) -> float:
        """Evaluates a math expression via AST securely."""
        ops: Dict[Type[ast.AST], Callable[..., float]] = {
            ast.Add: self.add, ast.Sub: self.subtract,
            ast.Mult: self.multiply, ast.Div: self.divide,
            ast.Mod: self.modulo, ast.Pow: self.power,
        }

        def _eval(node: ast.AST) -> float:
            if isinstance(node, ast.Constant) and isinstance(node.value, (int, float)):
                return float(node.value)
            if isinstance(node, ast.BinOp):
                left, right = _eval(node.left), _eval(node.right)
                return ops[type(node.op)](left, right)
            if isinstance(node, ast.UnaryOp):
                val = _eval(node.operand)
                if isinstance(node.op, ast.USub): return self.negate(val)
                if isinstance(node.op, ast.UAdd): return val
            if isinstance(node, ast.Expression):
                return _eval(node.body)
            raise TypeError(f"Unsupported expression component: {type(node).__name__}")

        self._suppress_recording = True
        try:
            result = _eval(ast.parse(expression, mode='eval'))
            self._suppress_recording = False
            self._record("evaluate", 0.0, 0.0, result, expression)
            return result
        except Exception as e:
            self._suppress_recording = False
            raise ValueError(f"Invalid expression: {e}")

    def memory_store(self, value: float) -> None:
        self._memory = float(value)
        self._record("memory_store", self._memory, 0.0, self._memory)

    def memory_recall(self) -> float:
        if self._memory is None:
            raise ValueError("Memory is empty.")
        val = self._memory
        self._record("memory_recall", 0.0, 0.0, val)
        return val

    def memory_clear(self) -> None:
        self._memory = None
        self._record("memory_clear", 0.0, 0.0, 0.0)

